-- GRAIN: one row per organization (CIK is unique)
-- SPINE_ENTITY: organization  (natural_key: CIK)
-- Generated by scripts/generate_staging_models.py from SOURCE_REGISTRY -- deterministic,
-- no LLM. Casts kept as landed (TEXT) -- add explicit type casts by hand once each
-- column's real type is confirmed; this generator has no semantic type knowledge.

with source as (

    select * from {{ source('ripple_raw', 'FED_SEC_CLOSED_END_FUND_INFORMATION') }}

),

renamed as (

    select
        "FILE_NO" as file_no,
        "CIK" as cik,
        "REGISTRANT_NAME" as registrant_name,
        "ADDRESS_1" as address_1,
        "ADDRESS_2" as address_2,
        "CITY" as city,
        "STATE" as state,
        "ZIP_CODE" as zip_code,
        "FILING_DATE" as filing_date,
        "FILING_TYPE" as filing_type,
        _INGESTED_AT as _loaded_at,
        '' as _source_url,
    'ENT_' || LEFT(MD5('CIK' || '|' || (CASE WHEN LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', ''))) = 0 OR LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', ''))) > 10 OR NOT REGEXP_LIKE(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), '^[0-9]+$') OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), 10, '0') = REPEAT('0', 10) OR (LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', ''))) >= 4 AND UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')) = REPEAT(LEFT(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), 1), LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', ''))))) OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), 10, '0') = REPEAT(LEFT(LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), 10, '0'), 1), 10) OR UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')) IN ('123456789', '987654321', '1234567890', '0987654321', '12345678', '87654321', '123456', '654321') OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), 10, '0') IN ('123456789', '987654321', '1234567890', '0987654321', '12345678', '87654321', '123456', '654321') THEN NULL ELSE LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CIK"), '[^0-9A-Za-z]', '')), 10, '0') END)), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

    from source

)

select * from renamed
qualify row_number() over (partition by cik order by _loaded_at desc) = 1
